x=pd.read_csv('data/explore.csv')
c=['nitrogen_ppm','phosphorus_ppm','potassium_ppm','soil_ph','irrigation_mm','seed_density','mulch_depth_cm','biochar_g','fungicide_ml','shade_pct']
